public class UserService {

    private final UserMapper userMapper;

    public UserService(UserMapper userMapper) {
        this.userMapper = userMapper;
    }

    public PageResult<UserResponse> page(UserQuery query) {
        // 分页插件生效后，这里不需要手写 count 与 limit
        Page<User> page = new Page<>(query.getPage(), query.getPageSize());
        LambdaQueryWrapper<User> wrapper = new LambdaQueryWrapper<User>()
                .eq(User::getStatus, query.getStatus())
                .like(StringUtils.hasText(query.getUsername()),
                        User::getUsername, query.getUsername())
                .orderByDesc(User::getId);
        Page<User> result = userMapper.selectPage(page, wrapper);
        return PageResult.of(
                result.getRecords().stream().map(UserResponse::from).toList(),
                result.getTotal(), query.getPage(), query.getPageSize());
    }
}

