 *
 * 注意：监控页会暴露全部 SQL 语句、表名、参数与执行计划，
 * 属于内部信息，必须限制来源 IP 并加鉴权，绝不可对公网开放。
 */
@Configuration
public class DruidMonitorConfig {

    @Bean
    public ServletRegistrationBean<StatViewServlet> druidStatView() {
        ServletRegistrationBean<StatViewServlet> bean =
                new ServletRegistrationBean<>(new StatViewServlet(), "/druid/*");
        bean.addInitParameter("loginUsername", System.getenv("DRUID_USER"));
        bean.addInitParameter("loginPassword", System.getenv("DRUID_PWD"));
        // 只允许本机访问，生产环境改成内网网段
        bean.addInitParameter("allow", "127.0.0.1");
        return bean;
    }
}

package com.example.config;

import com.github.benmanes.caffeine.cache.Caffeine;
import java.time.Duration;
import org.springframework.cache.CacheManager;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.cache.caffeine.CaffeineCacheManager;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 本地缓存配置。
 *
 * 两个必须设置的参数：
 *   maximumSize  没有上限的缓存等于内存泄漏。
 *   expireAfterWrite  没有过期的缓存等于永久脏数据。
 */
@Configuration
@EnableCaching
public class CacheConfig {

    @Bean
    public CacheManager cacheManager() {
        CaffeineCacheManager manager = new CaffeineCacheManager();
        manager.setCaffeine(Caffeine.newBuilder()
                // 条目数上限，超出后按 W-TinyLFU 淘汰
                .maximumSize(10_000)
                // 写入后过期，防止长期持有脏数据
                .expireAfterWrite(Duration.ofMinutes(10))
                // 打开统计，用于判断命中率是否值得
                .recordStats());
        return manager;
    }
}

