// 正确姿态：缓存失败要能降级到查库，而不是让整个接口失败
public UserResponse detail(long id) {
    String key = "user:" + id;
    try {
        Object cached = redisTemplate.opsForValue().get(key);
        if (cached != null) {
            return (UserResponse) cached;
        }
    } catch (Exception e) {
        // 缓存不可用时只记录，不阻断主流程（但必须有日志，不能静默）
        log.warn("Redis 读取失败，降级查库 key={}", key, e);
    }

    UserResponse response = UserResponse.from(loadOrThrow(id));
    try {
        redisTemplate.opsForValue().set(key, response, Duration.ofMinutes(30));
    } catch (Exception e) {
        log.warn("Redis 写入失败，本次不缓存 key={}", key, e);
    }
    return response;
}

// ── 生产者：业务事务提交后再发消息 ──────────────────
@Service
public class OrderService {

    private final RocketMQTemplate rocketMQTemplate;

    @Transactional(rollbackFor = Exception.class)
    public void createOrder(OrderCreateRequest request) {
        long orderId = orderRepository.insert(buildOrder(request));
        // 发消息失败不能让下单失败，记录待补偿即可
        try {
            rocketMQTemplate.syncSend("topic-order-created",
                    MessageBuilder.withPayload(new OrderCreatedEvent(orderId)).build());
        } catch (Exception e) {
            log.error("订单创建事件发送失败，转本地消息表补偿 orderId={}", orderId, e);
        }
    }
}

// ── 消费者：必须幂等，因为 MQ 一定至少投递一次 ──────────
@Component
@RocketMQMessageListener(topic = "topic-order-created",
        consumerGroup = "arsenal-demo-consumer")
public class OrderCreatedConsumer implements RocketMQListener<OrderCreatedEvent> {

    @Override
    public void onMessage(OrderCreatedEvent event) {
        // 幂等：同一个 eventId 处理过就跳过
        if (!idempotentGuard.tryMark(event.getEventId())) {
            log.info("重复消息已跳过 eventId={}", event.getEventId());
            return;
        }
        // 注意：抛异常才会触发重投，吞掉异常等于丢消息
        inventoryService.deduct(event.getOrderId());
    }
}

