package com.example.config;

import com.xxl.job.core.executor.impl.XxlJobSpringExecutor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * XXL-Job 执行器配置。
 *
 * 一个容易忽略的点：executor 的 ip 留空时由框架自动探测，
 * 在容器/多网卡环境下可能探测到错误的网卡地址，
 * 表现为「调度中心显示执行器在线，但任务一直不执行」。
 * 明确指定 ip 或配置网络策略可以避免。
 */
@Configuration
public class XxlJobConfig {

    private static final Logger log = LoggerFactory.getLogger(XxlJobConfig.class);

    @Value("${xxl.job.admin.addresses}")
    private String adminAddresses;

    @Value("${xxl.job.executor.appname}")
    private String appName;

    @Value("${xxl.job.executor.port}")
    private int port;

    @Bean
    public XxlJobSpringExecutor xxlJobExecutor() {
        XxlJobSpringExecutor executor = new XxlJobSpringExecutor();
        executor.setAdminAddresses(adminAddresses);
        executor.setAppname(appName);
        executor.setPort(port);
        log.info("XXL-Job 执行器已初始化 appName={} port={}", appName, port);
        return executor;
    }
}

package com.example.config;

import com.example.security.JwtAuthenticationFilter;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

/**
 * Spring Security 配置。
 *
 * 四条原则：
 *   1. 无状态：JWT 场景必须关掉 Session（STATELESS），否则水平扩容后
 *      会话落在某一台机器上，其他实例认不出你。
 *   2. CSRF 关闭：无状态 + 不用 Cookie 时 CSRF 不构成威胁；
 *      但如果你同时用了 Cookie，就必须开回来。
 *   3. 白名单必须显式列出，默认拒绝。
 *   4. 密码编码器用 BCrypt，不要用 MD5/SHA1（可暴力破解）。
 */
@Configuration
@EnableMethodSecurity
public class SecurityConfig {

    /** 无需认证即可访问的路径。只放登录、注册、健康检查、文档。 */
    private static final String[] WHITELIST = {
            "/api/v1/auth/login",
            "/api/v1/auth/register",
            "/actuator/health",
    };

    private final JwtAuthenticationFilter jwtAuthenticationFilter;

    public SecurityConfig(JwtAuthenticationFilter jwtAuthenticationFilter) {
        this.jwtAuthenticationFilter = jwtAuthenticationFilter;
    }

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
                .csrf(csrf -> csrf.disable())
                .sessionManagement(session ->
                        session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers(WHITELIST).permitAll()
                        // 接口文档在生产环境应关闭；开发环境放开
                        .requestMatchers("/v3/api-docs/**", "/swagger-ui/**").permitAll()
                        .requestMatchers(HttpMethod.OPTIONS, "/**").permitAll()
                        // 其余一律要认证：默认拒绝，而不是默认放行
                        .anyRequest().authenticated())
                // JWT 过滤器放在用户名密码过滤器之前
                .addFilterBefore(jwtAuthenticationFilter,
                        UsernamePasswordAuthenticationFilter.class);
        return http.build();
    }

    /** BCrypt 自带盐值且可调计算强度，是密码存储的默认选择。 */
    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}

// 方法级鉴权：把「谁能调这个接口」写在方法上，一眼可见。
@RestController
@RequestMapping("/api/v1/users")
public class UserController {

    // 需要 ADMIN 角色
    @PreAuthorize("hasRole('ADMIN')")
    @DeleteMapping("/{id}")
    public ApiResponse<Void> delete(@PathVariable long id) {
        userService.delete(id);
        return ApiResponse.ok();
    }

    // 只允许本人或管理员（水平越权防护，SEC-AUTH-001）
    @PreAuthorize("#id == authentication.principal.userId or hasRole('ADMIN')")
    @GetMapping("/{id}/profile")
    public ApiResponse<UserProfileResponse> profile(@PathVariable long id) {
        return ApiResponse.ok(userService.profile(id));
    }
}

// 注意：@PreAuthorize 只解决「能不能进这个接口」，
// 不解决「这条数据是不是你的」。列表类接口必须把当前用户
// 作为查询条件传下去，不能靠前端传 userId。

package com.example.config;

import cn.dev33.satoken.interceptor.SaInterceptor;
import cn.dev33.satoken.router.SaRouter;
import cn.dev33.satoken.stp.StpUtil;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

/**
 * Sa-Token 拦截器注册。
 *
 * 关键设计：全局拦截器只做「是否登录」检查，
 * 权限粒度交给方法上的 @SaCheckPermission —— 
 * 把权限规则全部堆在拦截器里，会变成一个没人敢改的 if 长列表。
 */
@Configuration
public class SaTokenConfig implements WebMvcConfigurer {

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(new SaInterceptor(handler ->
                        // 只拦「登录校验」，白名单显式列出
                        SaRouter.match("/**")
                                .notMatch("/api/v1/auth/**")
                                .notMatch("/actuator/**")
                                .check(r -> StpUtil.checkLogin())))
                .addPathPatterns("/**");
    }
}

package com.example.config;

import io.swagger.v3.oas.models.OpenAPI;
import io.swagger.v3.oas.models.info.Info;
import io.swagger.v3.oas.models.security.SecurityRequirement;
import io.swagger.v3.oas.models.security.SecurityScheme;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * OpenAPI 元信息。
 *
 * 注册 SecurityScheme 后，Swagger UI 右上角会出现
 * 「Authorize」按钮，可以直接填 JWT 调试受保护接口 ——
 * 不注册的话每次调试都要手工改 header，很影响使用率。
 */
@Configuration
public class OpenApiConfig {

    private static final String SCHEME = "bearerAuth";

    @Bean
    public OpenAPI openAPI() {
        return new OpenAPI()
                .info(new Info()
                        .title("军火库示例服务")
                        .version("1.0.0")
                        .description("所有接口统一返回 ApiResponse；"
                                + "业务错误码见错误码表"))
                .addSecurityItem(new SecurityRequirement().addList(SCHEME))
                .components(new io.swagger.v3.oas.models.Components()
                        .addSecuritySchemes(SCHEME, new SecurityScheme()
                                .type(SecurityScheme.Type.HTTP)
                                .scheme("bearer")
                                .bearerFormat("JWT")));
    }
}

package com.example.config;

import io.micrometer.core.aop.TimedAspect;
import io.micrometer.core.instrument.MeterRegistry;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 自定义业务指标。
 *
 * 为什么需要它：HTTP 指标只能告诉你「接口变慢了」，
 * 但告诉不了你「是哪一类业务变慢了」。
 * 加上业务维度的计数器，才能把技术指标映射回业务问题。
 *
 * 指标命名约定：<域>_<对象>_<动作>_<单位>，
 * 例如 order_create_total、import_rows_processed_total。
 */
@Configuration
public class MetricsConfig {

    /** 开启 @Timed 注解支持（AOP 代理），否则 @Timed 不会生效。 */
    @Bean
    public TimedAspect timedAspect(MeterRegistry registry) {
        return new TimedAspect(registry);
    }
}

