                .description("成功创建的订单数")
                .register(registry);
        this.orderFailedCounter = Counter.builder("order_create_failed_total")
                .description("创建失败的订单数")
                .tag("reason", "business")
                .register(registry);
    }

    @Transactional(rollbackFor = Exception.class)
    public long create(OrderCreateRequest request) {
        try {
            long id = orderRepository.insert(buildOrder(request));
            orderCreatedCounter.increment();
            return id;
        } catch (BizException e) {
            orderFailedCounter.increment();
            throw e;
        }
    }
}

public record UserResponse(Long id, String username, String mobile) {

