package com.example.support;

import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.boot.testcontainers.service.connection.ServiceConnection;
import org.springframework.context.annotation.Bean;
import org.testcontainers.containers.MySQLContainer;

/**
 * 集成测试用真实数据库。
 *
 * 关键：容器是 static 且只启动一次（@ServiceConnection 会把
 * 连接信息自动注入 datasource 配置），所有测试类共享。
 * 每个测试类起一个容器会让测试套件慢到没人愿意跑。
 *
 * 另一个好处是：它验证的是真实的 MySQL 行为，
 * 包括字符集、排序规则、唯一索引冲突的具体错误码 ——
 * 这些用 H2 永远测不出来。
 */
@TestConfiguration(proxyBeanMethods = false)
public class TestcontainersConfig {

    @Bean
    @ServiceConnection
    public MySQLContainer<?> mysqlContainer() {
        return new MySQLContainer<>("mysql:8.0.36")
                // 必须指定 utf8mb4，否则测不出 emoji 相关的字符集问题
                .withCommand("--character-set-server=utf8mb4",
                        "--collation-server=utf8mb4_general_ci")
                .withReuse(true);
    }
}
